from pathlib import Path
import json,re

W=Path(__file__).parent
ROOT=W.parents[3]
BASE=(ROOT/'state/STANDARDS_AND_TESTS.md').read_text()
INDEX=json.loads((W/'records-index.json').read_text())[:60]
EDITS=[]
COVER={i:{'file':r['file'],'decision':'exclude','titles':[],'explanation':'Application of carried law or case-specific disposition; no independent reusable operative change.'} for i,r in enumerate(INDEX,1)}

def source(i, prop):
    r=INDEX[i-1]
    return f"Canonical Decision Record `{r['file']}`, Public Projection / Holdings / {prop}, {r['date']}"

def include(ids,title,why='New or materially clarified reusable instruction, with application-specific results excluded.'):
    if isinstance(ids,int): ids=[ids]
    for i in ids:
        COVER[i]['decision']='mixed'
        if title not in COVER[i]['titles']: COVER[i]['titles'].append(title)
        COVER[i]['explanation']=why

def add(ids,title,area,question,rule,authorities,effective=None,extras=''):
    if isinstance(ids,int): ids=[ids]
    if effective is None: effective=INDEX[max(ids)-1]['date']
    text=f'### {title}\n\n**Governing question:** {question}\n\n**Current rule:** {rule}\n\n**Authority by component:**\n\n'
    text+='\n'.join('- '+a for a in authorities)
    text+=f'\n\n**Present operation effective:** {effective}.\n'
    if extras: text+='\n'+extras.strip()+'\n'
    EDITS.append(dict(title=title,area=area,mode='add',text=text))
    include(ids,title)

def modify(ids,title,rule,authorities,effective,question=None,replace=None):
    if isinstance(ids,int): ids=[ids]
    m=re.search(r'^### '+re.escape(title)+r'\n',BASE,re.M)
    assert m,title
    e=re.search(r'^#{2,3} ',BASE[m.end():],re.M)
    t=BASE[m.start():m.end()+e.start() if e else len(BASE)].rstrip()+'\n'
    area=re.findall(r'^## (.+)$',BASE[:m.start()],re.M)[-1]
    if question: t=re.sub(r'\*\*Governing question:\*\*[^\n]*','**Governing question:** '+question,t, count=1)
    t=t.replace('\n**Authority by component:**','\n'+rule.strip()+'\n\n**Authority by component:**',1)
    pos=t.index('**Present operation effective:**')
    t=t[:pos]+'\n'.join('- '+a for a in authorities)+'\n\n'+t[pos:]
    t=re.sub(r'\*\*Present operation effective:\*\*[^\n]*','**Present operation effective:** '+effective,t,count=1)
    for a,b in (replace or {}).items():
        assert a in t,(title,a)
        t=t.replace(a,b)
    EDITS.append(dict(title=title,area=area,mode='replace',text=t))
    include(ids,title)

CR='Criminal procedure, evidence, and punishment'
FC='Federal courts and judicial remedies'
SP='Speech, association, and elections'
LAB='Labor, employment, and maritime law'
CV='Civil rights and constitutional remedies'

add(1,'Reserved legal challenges and acceptance of responsibility',CR,
    'Whether preserving a nonfrivolous legal challenge defeats an otherwise warranted §3E1.1 adjustment.',
    'A sentencing court may not deny an otherwise warranted acceptance-of-responsibility adjustment solely because the defendant presents a nonfrivolous legal or constitutional challenge unrelated to admitted factual guilt. A guilty plea reserving such a challenge is not a categorical bar, but neither the plea nor the prosecutor’s recommendation guarantees the adjustment. The court must assess actual acceptance on supported lawful grounds. False factual denials, sham factual assertions and conduct inconsistent with acceptance remain relevant; an unsuccessful legal position alone is not such conduct.',
    ['Protected legal challenge and distinct actual-acceptance inquiry: '+source(1,'V-A. A reserved legal challenge alone does not defeat acceptance credit')+'; Kennedy’s opinion, eight direct joins.'],
    extras='**Exceptions and limits:** This is the Guidelines instruction, not a categorical constitutional immunity from every litigation-related sentencing consequence. Review of legal error and genuine factual sentencing judgments remains governed by the carried Guidelines-review rules.')

modify([2],'Personal arms protection, incorporation and necessary acquisition',
    'Personal arms protection does not itself require extending §925(a)(1)’s governmental-use exception to the §922(d)(9) and §922(g)(9) domestic-violence-misdemeanor restrictions. For the covered official-use category, an adjudicated connection to violent misuse together with the statutory force or threatened-deadly-weapon element, domestic relationship, counsel and jury-waiver protections, and conviction-relief qualifications supplies a concrete justification for withholding that exception. Public employment does not remove that connection or make the issued firearm unavailable to its possessor.',
    ['Official-use exception and its conviction safeguards: '+source(2,'Personal arms protection does not compel this governmental-use exception; Statutory scope retained throughout')+'; Souter’s unanimous opinion.'],
    'Fraternal Order of Police, 1998-10-07, for the defined official-use exception; Love and Hale retain their existing component dates.',
    replace={'No comprehensive weapons classification, scrutiny tier, closed regulatory list, universal defensive-purpose rule or final §922(o) invalidity is established.':'No comprehensive weapons classification, scrutiny tier, closed regulatory list, universal defensive-purpose rule or final §922(o) invalidity is established. Fraternal Order of Police does not decide every private-possession application, every misdemeanor disability, an improperly classified conviction or a missing statutory safeguard.'})

modify([3,6,7],'Commerce connection, mechanism, and class-wide effects',
    'The recipient-possession restrictions in §§922(g)(1) and (g)(9) have a distinct fitted connection to the corresponding §922(d)(1) and (d)(9) prohibited-recipient supply restrictions: preventing the disqualified recipients’ acquisition and retention from evading or materially impairing those valid supply restrictions supports inclusion under the Commerce and Necessary and Proper Clauses. The enacted interstate conditions remain separately provable offense requirements; historical interstate movement alone is not the constitutional mechanism. Section 922(g)(1) requires neither contemporaneous movement nor an individually substantial or direct interstate effect beyond its retained nexus construction. The prosecution must prove the enacted nexus beyond a reasonable doubt.',
    ['Domestic-violence recipient/supply connection: '+source(3,'III. The possession restriction supports the distinct prohibited-recipient supply regime')+'; eight direct joins.',
     'Convicted-recipient firearm and ammunition connection: '+source(6,'II. Gonzalez’s ammunition conviction rests on a distinct supply-and-recipient connection')+'; eight direct joins.',
     'Distinct statutory nexus and refusal to add a direct-effect element: '+source(7,'I. The supply restriction and recipient-possession rule supply the constitutional connection; II. The requested direct-effect instruction would add an element')+'; unanimous opinion.'],
    '1998-10-09 for §922(g)(9)’s recipient/supply connection; 1998-10-22 for §922(g)(1)’s connection; 1998-10-29 for its distinct no-added-direct-effect instruction. Earlier architecture and component dates remain unchanged.')

add(4,'Coordinate fixation of state-federal submerged-land boundaries','Property and takings',
    'Whether a state-federal submerged-land boundary fixed by coordinates in a final Supreme Court decree moves with the coast.',
    'Under 43 U.S.C. §1301(b), a state-federal boundary fixed by coordinates in a final decree of this Court remains immobilized at the decreed coordinates and does not move with later coastline change. The decree’s complete coordinate schedule, including its datum, zones, precision, sequence, segments and arcs, controls; an illustrative map does not replace it.',
    ['Coordinate-fixation consequence and schedule priority: '+source(4,'The complete coordinates fix and immobilize the boundary')+'.'],
    extras='**Exceptions and limits:** This rule does not allocate an unpresented State’s territory, decide reserved property interests or change the entitlement used to select the decreed line.')

add(5,'Columbus firearm definitions and separate fault','Arms and firearms',
    'The operative classifications and fault conditions under Columbus §§2323.11, 2323.31 and 2323.32.',
    'Section 2323.31(A)’s silence retains §2301.21(B)’s enacted recklessness default unless the offense plainly indicates strict liability. The City must establish heedless indifference and perverse disregard of a known risk that the prohibited circumstance was likely to exist. That condition addresses ignorance of an intelligibly defined characteristic; it cannot supply a missing legal boundary.\n\nSection 2323.11(G)(1) concerns a semiautomatic center-fire rifle or carbine accepting an existing detachable magazine of twenty rounds or more, whether or not its owner possesses that magazine. Hypothetical future magazines do not establish compatibility. Subsection (G)(2) concerns a semiautomatic shotgun accepting more than six rounds of actual compatible ammunition; different real shell lengths do not defeat the criterion. Subsection (G)(3)(b) concerns a semiautomatic handgun originally designed to accept a detachable magazine holding more than twenty rounds; later conceivable magazines do not establish original design. Each retains separate fault.\n\nBoth (G)(3)(a) modification branches are invalid as written because they fail to identify whether actual conversion, design descent or resemblance supplies the prohibited relationship. Dependent restoration or parts references cannot independently impose liability through those branches. Subsection (G)(4) instead reaches an existing firearm actually capable of restoration to a former operable condition meeting a valid (G)(1), (G)(2) or (G)(3)(b) predicate, with separate fault; raw materials and theoretical reconstruction are insufficient. Subsection (G)(5)’s first branch requires objective conversion design or identified conversion purpose connecting a part or combination to a valid predicate. Its second requires a combination from which such a weapon may readily be assembled, possessed or controlled by the same person, with actual practical assembly and separate fault. No numerical time, cost or skill threshold is supplied.\n\nSection 2323.32(A) separately requires knowing possession of the large-capacity magazine defined by §2323.11(F): a box, drum, clip or other container holding more than twenty rounds for continuous feeding into a semiautomatic firearm, excluding magazines designed only for .22-caliber rimfire cartridges. Its fault and threshold are not the rifle definition’s fault and twenty-or-more threshold.',
    ['Default fault and valid definition boundaries: '+source(5,'II–VIII; X. The other magazine exceptions retain their full alternatives')+'; eight direct joins to these parts.',
     'Invalid predicates and state-law severability: '+source(5,'V. Both modification branches lack the relationship that defines the offense; XI. Relief follows the invalid branches and actual Ohio severability')+'; eight direct joins.'],
    extras='**Exceptions and limits:** The former-city-registration exemption requires actual lawful possession and registration of the particular firearm in 1989; its magazine clause requires the specified relationship to the registered weapon. The NFA magazine branch alternatively reaches a magazine belonging to an NFA-registered firearm or possessed by the owner of one; the owner alternative does not require compatibility. The inert-object branch requires the specified relationship to an assault weapon rendered wholly inoperable or inert, not readily reactivated, and kept as a trophy, souvenir, curio or museum piece. The invalid modification branches and dependent references must receive actual Ohio severability analysis; no new registry or rewritten offense follows. Authority: the same Record, Holdings IX–XI; seven direct joins to IX and eight to X–XI. These constructions do not adjudicate an independent substantive arms challenge or any owner’s liability.')

add(6,'Attribution and reliability of other-person conduct at Guidelines sentencing',CR,
    'When conduct by another participant may enter the offense-level calculation.',
    'For conduct during the offense, preparation, or attempts to avoid detection or responsibility, §1B1.3(a)(1)(A) permits attribution of supported acts the defendant aided or abetted. Subsection (B) separately requires another participant’s acts to be within jointly undertaken criminal activity, in furtherance of it, and reasonably foreseeable in connection with it. Reliable evidence from another defendant’s trial is not categorically inadmissible merely because the sentenced defendant was neither a party nor represented there; the applicable preponderance burden, Rule 32 opportunity to address material factual assertions, and independent evidentiary and Guidelines safeguards remain.',
    ['Distinct attribution routes and other-trial evidence safeguards: '+source(6,'V. Supported assistance and joint activity permit the machinegun base level; VIII. Other-trial evidence and within-range selection remain limited sentencing decisions')+'; eight direct joins.'])

add(6,'Weapon-use and criminal-history Guidelines departures',CR,
    'The authorized grounds and extent of weapon-use and underrepresented-criminal-history departures.',
    'Section 5K2.6 permits an increase when a weapon or dangerous instrumentality was used or possessed in committing the offense; extent ordinarily depends on dangerousness, manner of use and danger to others, and firearm discharge may warrant a substantial increase where the existing level does not already account for that conduct. Section 4A1.3 separately permits departure on reliable information that the initial criminal-history category inadequately reflects the seriousness of past conduct or likelihood of further crime. Section 4A1.2 application note 8 permits consideration of stale convictions for similar or serious dissimilar conduct. Reasons supporting the selected extent are required; an empty category-by-category recital is not.',
    ['Weapon-use ground and criminal-history information and extent: '+source(6,'VI. Discharge supports the separate three-level departure; VII. The presented criminal-history objections do not defeat category IV')+'; eight direct joins.'],
    extras='**Exceptions and limits:** Education, vocational skills and employment record are ordinarily irrelevant to departure under §§5H1.2 and 5H1.5; their uses for supervision conditions do not authorize an upward prison-range departure. Section 5H1.4 is not unconditional upward-departure authority for drug dependence or abuse. A properly presented invalid-factor claim retains Koon’s classification and whole-record remedial inquiry. No particular departure amount follows from these rules.')

add(8,'Union-security wording and independent fair-representation claims',LAB,
    'Whether use of statutory membership language or a standalone NLRA timing objection establishes a judicial fair-representation claim.',
    'Negotiating a union-security clause in §8(a)(3)’s statutory membership terms does not alone breach fair representation. The established restrictions on compulsory financial obligations remain, and arbitrariness, discrimination or bad faith requires its own operative support; under arbitrariness, the negotiated choice must fall outside the broad range of reasonableness under the relevant facts and law. Statutory wording does not authorize compelled full membership, misleading notice, nonchargeable collections or unlawful enforcement. A claim alleging only that a grace-period arrangement violates the NLRA belongs initially to the NLRB. A federal court may decide a statutory question necessary to an independently supported fair-representation claim; relabeling statutory inconsistency supplies no independent judicial basis.',
    ['Wording, fair-representation standards and Board/court allocation: '+source(8,'1. Statutory membership wording does not alone breach fair representation; 2. A standalone statutory timing claim belongs initially to the Board')+'; unanimous opinion.'],
    extras='**Open question:** Whether a thirty-day grace period restarts after a break, how prior employment counts and whether a particular notice or enforcement practice is lawful remain separate questions.')

add(10,'Selective racial restructuring of access to lawful remedies','Education and equal protection',
    'A State’s relocation of authority over otherwise lawful racial remedies to a more remote political process.',
    'A supported claim that a State selectively moves authority over otherwise lawful racial remedies to a more remote political process requires examination of the resulting unequal political burden; calling the foreclosed measures preferences does not answer that claim. Interim protection must correspond to the demonstrated threatened loss of access to otherwise available lawful racial remedies and leave independently lawful provisions operative to the extent severable under state law. This does not require a preference or validate an unconstitutional program. The racial political-process rule does not decide a sex-based theory: an actual sex classification requires the important-objective and substantial-relationship inquiry without presuming that every statewide withdrawal of policy creates such a classification.',
    ['Political-process inquiry, distinct sex analysis and fitted preliminary protection: '+source(10,'I. Selective racial restructuring requires a political-process inquiry; II. The sex theory requires a distinct inquiry; IV. Preliminary relief must correspond to the supported injury')+'; five direct joins.'],
    extras='**Exceptions and limits:** Title VII’s permission for defined voluntary affirmative action does not alone preempt state withdrawal of that policy or guarantee subordinate entities authority to adopt it. Actual conflict with a federal duty or binding remedy remains subject to federal supremacy and applicable savings provisions. Authority: the same Record, Holding III, all nine Justices.')

add(11,'Commercial offers and readiness under the patent on-sale bar','Patents',
    'When the then-effective §102(b) on-sale bar applies before a United States patent application.',
    'Before the date one year before the United States application, the actual claimed invention must both be subject to a commercial offer for sale in the United States and be ready for patenting. Readiness may be proved by reduction to practice or drawings or descriptions sufficiently specific to enable a person skilled in the art to practice the invention. A working prototype is sufficient but unnecessary. Both conditions must be proved: substantial commercial commitment cannot complete an incomplete conception, later development does not retroactively establish readiness, and an open-ended substantial-completion judgment does not replace enabling disclosure.',
    ['Two-condition bar, readiness alternatives and critical-date limits: '+source(11,'Commercial offer and readiness for patenting')+'; unanimous opinion.'],
    extras='**Exceptions and limits:** Preliminary negotiations, proposals for future inventive research and incomplete conceptions are insufficient. Genuine controlled experimentation remains distinct from ordinary commercial exploitation; no separate experimental-use dispute was decided.')

add(12,'Knowing false best-execution undertakings in securities transactions','Civil RICO and securities liquidation',
    'Primary deception when a broker accepts an uninstructed customer order while intending not to perform its represented execution undertaking.',
    'A broker-dealer that accepts a customer order without price instructions while knowingly intending to disregard the best-execution undertaking it represents can commit primary fraud when the representation is materially false and the other private-action elements are proved. Breach of care, inferior execution, fiduciary breach or broker status alone is insufficient. The customer must prove the actual undertaking, material deception and culpability, legally sufficient reliance, causation and actual loss. Execution at the national best bid and offer or through SOES supplies no categorical safe harbor when genuine evidence supports knowing disregard of reasonably available better terms. Contemporary reasonable availability includes order size, trading characteristics, speed, clearing costs, access expense and difficulty, as well as price; later law or technology does not itself establish earlier obligations or feasibility.',
    ['Knowing undertaking and independent private-action elements; contemporary execution inquiry: '+source(12,'A knowingly false execution undertaking can be primary securities fraud; The disputed contemporary execution evidence precludes the categorical summary judgment')+'; unanimous opinion.'],
    extras='**Exceptions and limits:** No universal venue, best-possible-price guarantee or search of every quotation is imposed. Custom is relevant but not conclusive immunity for a knowingly false undertaking. General primary-fraud recklessness is unresolved; the separate assistance standard is not imported.')

add(13,'Clear collective waiver of a statutory discrimination forum','Arbitration',
    'Whether a collective agreement surrenders an employee’s judicial forum for an independent federal discrimination claim.',
    'A union-negotiated surrender of that judicial forum must be clear and unmistakable: the agreement must identify the statutory claim or an equivalent class of federal rights. Submission of contractual disputes, employment coverage, final grievance decisions or a clause preserving contractual legality does not by itself submit every independent statutory cause. Separate instruments require separate examination. The same employment event can present contractual and statutory questions without merging their sources.',
    ['Clear-and-unmistakable statutory identification and instrument-specific assent: '+source(13,'Neither instrument clearly waives the statutory judicial forum')+'; unanimous opinion.'],
    extras='**Open question:** Enforceability of a sufficiently explicit collective waiver and general FAA coverage remain undecided.')

add(14,'Reserved federal claims and preclusion of litigated state facts',FC,
    'Whether reservation of a federal cause displaces §1738 issue preclusion following state compensation litigation.',
    'Reservation of a federal cause does not exempt an identical factual issue from the rendering State’s lawful preclusion rules when the issue was actually and necessarily litigated with a full and fair opportunity by parties bound in proceedings that State recognizes. England’s protection following federal abstention does not create a unilateral right to contradict such a necessary finding in separate state compensation litigation. Preclusion remains issue-specific; a binding fact does not automatically preclude the entire federal claim, every federal element or a distinct legal assessment.',
    ['Rendering-state effect, reservation and issue-specific limits: '+source(14,'I. Reservation of the federal cause does not erase a necessary, fairly litigated state finding')+'; unanimous Part I.'])

modify(16,'Actual and justifiable reliance for the actual-fraud discharge exception',
    'Use of a credit card to obtain an advance represents a present intention to repay, not current solvency or an objectively reasonable repayment prospect. On that actual-fraud theory, the creditor must prove by a preponderance that the contemporaneous professed intention was false and deceptive. Financial condition, losses and borrowing patterns may prove state of mind, but inability to pay or unreasonable optimism alone cannot replace the subjective inquiry. The debtor’s denial is not conclusive; no confession, mandatory factor count or additional plan to file bankruptcy is required. Repayment creates no safe harbor for a deliberately false promise.',
    ['Credit-card representation and contemporaneous deceptive intent: '+source(16,'Card use communicates an intent to repay, not a warranty of solvency')+'; unanimous opinion.'],
    'Rembert, 1998-12-01, for the credit-card intent component; Field and In re Cohen retain their earlier component dates.')

modify(17,'Personal residential sharing and limited exposure',
    'Actual host-authorized joint use of a deliberately screened home for a private activity can establish each invited occupant’s own privacy interest despite brief duration, commercial purpose or illegality, separately or together. A prior recurring relationship, overnight arrangement or independent key is not invariably required for that shared domestic privacy. Mere permission to enter, another person’s rights or a desire to conceal crime alone is insufficient.',
    ['Brief host-authorized domestic sharing and its limits: '+source(17,'I. Each respondent has a personal interest in the shared domestic privacy')+'; Breyer Part I, Stone-Zsela, Stevens, Souter, Ginsburg and Breyer directly join.'],
    'Minnesota v. Carter and Johns, 1998-12-01, extends Fields’s shared-privacy component; Fields’s other components retain 1998-02-09.',
    replace={'These rules do not classify every shared yard, resolve the particular observation as a search or establish a general police-created-exigency doctrine.':'These rules do not classify every shared yard, resolve the Fields or Carter observation as a search or establish a general police-created-exigency doctrine. Carter supplies no controlling search application and no Marks synthesis between reserved analysis and conclusive nonsearch grounds.'})

add(18,'Class-specific foreclosure of ordinary municipal protection','Education and equal protection',
    'Ordinary rational-basis review of a municipal charter’s combined withdrawal and prospective prohibition of ordinary protection for a named class.',
    'The actual breadth of a class-specific exclusion from ordinary municipal nondiscrimination protection must bear a rational relationship to legitimate objectives. Municipal scope, continued generally applicable remedies and access to higher government do not by themselves answer an unexplained selective disability across ordinary civic activity. Fiscal, regulatory, associational or durable-policy interests must rationally relate to that actual disadvantage; no finding about each voter’s private motive is required. This rule does not prohibit every repeal or require enactment of a particular protection.',
    ['Actual-breadth rationality and rejection of municipal-scope cure: '+source(18,'The municipal class-specific foreclosure fails ordinary rational-basis review')+'; seven direct joins.'],
    extras='**Exceptions and limits:** Genuine expression and religious-exemption questions retain their own predicates. The ruling establishes no heightened sexual-orientation scrutiny or universal entitlement to favorable legislation. Relief removes the unlawful barrier without imposing a municipal code; any independently lawful remainder requires actual state-law severability.')

add(19,'Traffic citations and the custodial-arrest search exception',CR,
    'Whether issuing a traffic citation authorizes a full search incident to arrest.',
    'Issuing a citation without custodial arrest does not trigger the full search-incident-to-arrest exception. Unexercised arrest authority, general roadside risk and the observed traffic offense do not substitute for its custody predicate. A further search requires its own recognized basis. Terry requires supported suspicion that the person is armed and dangerous; a Long vehicle search requires specific facts supporting danger and possible immediate control of weapons and remains confined to weapon-hiding areas. Exit directions alone authorize neither frisk nor full search. Consent and the automobile exception retain their independent conditions.',
    ['Custody predicate and distinct protective-search bases: '+source(19,'I. A citation does not trigger the full custodial-arrest search exception')+'; unanimous Part I.'],
    extras='**Exceptions and limits:** Robinson’s categorical rule remains for an actual qualifying lawful custodial arrest. No later arrest may be invented to validate an earlier intrusion retrospectively, and no universal traffic-evidence exclusion rule follows.')

add(21,'Consumer collateral retention and reaffirmation approval','Bankruptcy',
    'What then-effective §§521(2) and 524 require when an individual consumer debtor proposes to retain collateral.',
    'Section 521(2) requires the statement of retention or surrender for covered scheduled consumer debts secured by estate property within thirty days after filing or by the creditors’ meeting, whichever is earlier, subject to a for-cause extension fixed within that period. Exemption, redemption or reaffirmation must be specified when applicable. The debtor must perform the lawful stated intention within forty-five days after notice, subject to a for-cause extension fixed within those forty-five days. With subparagraph (C)’s preservation of debtor and trustee rights, those duties do not themselves make surrender, redemption and reaffirmation exclusive substantive options. Continued payment and retention remain permissible insofar as existing law and the enforceable agreement permit; no lien stripping, excuse of lawful default or judicially reduced installment redemption follows.\n\nFor an unrepresented individual covered by §524(c)(6)(A), approval independently requires both absence of undue hardship to the debtor or a dependent and the debtor’s best interest. Agreement or signature alone satisfies neither condition. Subsection (6)(B)’s exception concerns consumer debt secured by real property. Voluntary repayment under §524(f) does not restore enforceable discharged personal liability; all other §524(c)–(d) conditions remain.',
    ['Mandatory timing without an exclusive retention election; independent approval safeguards: '+source(21,'Mandatory notice and performance do not create an exclusive retention election; This agreement remains subject to independent debtor-protection approval')+'; unanimous opinion.'],
    extras='**Exceptions and limits:** Actual lawful agreement terms, default rules, lien rights, stay provisions and discharge rules govern independently. Section 521(2) alone supplies no new acceleration or forfeiture command. No unseen bankruptcy-default clause is construed or held invalid.')

modify(22,'Preserved protected-silence and personal-intent errors on federal habeas review',
    'The State-borne Chapman rule also governs a properly available constitutional trial error in a commutation instruction affecting a capital jury’s choice between death and life without parole: the State must show beyond a reasonable doubt from the whole penalty record that the error did not contribute to the actual death sentence. Consider the complete charge, mitigation, prosecution theory and supported jury requests, rather than what a hypothetical properly instructed jury could have imposed. A corrective direction or strong aggravation is not independently conclusive. Boyde’s error-identification inquiry does not itself establish the effect required for relief. The actual reasoning must perform that causal inquiry under the governing burden, but no prescribed words, citation or separate heading is indispensable. An available violation failing the State’s showing requires conditional sentence relief allowing a reasonable opportunity for a lawful new penalty proceeding; a method error alone does not establish entitlement to a writ.',
    ['Defined commutation-misinformation category, Chapman burden and conditional penalty relief: '+source(22,'I. Chapman governs this available capital-selection misinformation claim')+'; Stone-Zsela, O’Connor, Souter, Ginsburg and Breyer directly join Part II.',
     'Separate substantive effect inquiry without a verbal-formula requirement: '+source(22,'II. The required effect inquiry is substantive, not a verbal formula')+'; eight Associates directly join Part III.'],
    'Calderon v. Coleman, 1998-12-14, adds the defined commutation-instruction category; Brecht, O’Neal and Roy retain their earlier component operation.',
    question='Harmlessness for the protected-silence, personal-intent and commutation-misinformation categories properly available on federal habeas.',
    replace={'Other reserved habeas categories, prejudice incorporated into a different constitutional claim, structural error and independent habeas gates retain their separate treatment.':'The defined commutation-instruction category is now governed by Calderon v. Coleman. Other reserved habeas categories, prejudice incorporated into a different constitutional claim, structural error and independent habeas gates retain their separate treatment.'})

add(23,'At-will employment loss from a federal-witness conspiracy',CV,
    'Injury to person or property under the civil remedy for the federal-witness clauses of §1985(2).',
    'Loss of at-will employment and wages caused by acts furthering the forbidden federal-witness conspiracy may be injury to person or property without a constitutional entitlement to continued employment. The pertinent clauses require a conspiracy of two or more to deter a party or witness by force, intimidation or threat from attending federal court or testifying freely, fully and truthfully, or to injure the party or witness for attendance or testimony. The prohibited object, federal-witness nexus, acts, causation, damages and applicable defenses remain necessary. At-will status does not erase the economic interest against unlawful interference.',
    ['Statutory injury independent of constitutional employment entitlement and preserved predicates: '+source(23,'Loss of at-will employment may be the injury caused by a forbidden federal-witness conspiracy')+'; unanimous opinion.'],
    extras='**Open question:** The rule does not decide whether particular corporate agents can conspire, every witness-definition question or punitive and reinstatement remedies.')

add(24,'Vertical supplier choice and antitrust competitive injury','Antitrust',
    'Per se boycott classification and competitive injury for a buyer’s agreement to replace one supplier with another.',
    'A single buyer’s agreement to buy services from one supplier instead of another is not a per se group boycott absent horizontal concerted exclusion or another established per se basis. Intent to injure a rival, fraudulent purpose and lack of an apparent efficiency justification do not themselves supply that category. The surviving §1 competitive-effects theory requires rule-of-reason review. Regulatory deception, consumer overcharges and elimination of one supplier do not alone establish injury to the competitive process; competitive injury and the elements of the actual claim must be proved.',
    ['Vertical classification and distinct competitive-process requirement: '+source(24,'This vertical supplier substitution is not a per se group boycott; Regulatory fraud and harm to one supplier do not replace competitive injury')+'; unanimous opinion.'],
    extras='**Exceptions and limits:** Genuine horizontal restraints, actual price fixing and other established categories retain their own requirements. Rejecting per se treatment neither establishes reasonableness nor immunizes fraud. Attempted-monopolization elements are not automatically transferred to a §2 conspiracy theory.')

add([25,42],'Mandatory ceilings on total candidate campaign spending',SP,
    'The First Amendment standard for compulsory limits on a candidate’s total campaign advocacy.',
    'A mandatory ceiling on the total amount of candidate or candidate-committee advocacy receives the demanding review applicable to expenditures, including judicial campaigns. Spending contributed, personal or family money remains candidate expenditure rather than a donor-contribution limit. Reducing campaign costs or equalizing resources cannot justify the restraint; corruption, official-work and public-confidence concerns require fit to the actual source-independent restriction. Judicial impartiality and its appearance are weighty interests, but they do not themselves justify barring further personally financed or qualifications-related advocacy without the necessary connection. Ability to communicate meaningfully below a ceiling does not justify prohibiting additional advocacy.',
    ['Expenditure classification and rejected municipal rationales: '+source(25,'Candidate expenditures and the asserted municipal interests')+'; unanimous opinion.',
     'Judicial-campaign application and independent consideration of impartiality: '+source(42,'Judicial-campaign expenditures and the preliminary protection')+'; unanimous opinion.'],
    effective='Suster v. Marshall, 1999-01-28, for judicial-campaign coverage; Kruse’s total-expenditure component, 1998-12-16',
    extras='**Exceptions and limits:** Separate contribution, solicitation, disclosure, recusal, ethics and voluntary-financing conditions retain their distinct inquiries. No empirical waiting period, completed-bribe prerequisite or general validation of those alternatives is created.')

add(27,'No implied public-access cable damages action under §531(e)',CV,
    'Whether §531(e)’s editorial-control prohibition itself authorizes a private damages action.',
    'Section 531(e), in its governing Cable Act setting, does not itself create an implied private damages action against the cable operator. The protected class, direct statutory prohibition, asserted enforcement gap and limited lower-court recognition do not establish congressional intent for that remedy. Appropriate-relief principles presuppose a cognizable action and cannot supply the missing action. Independently authorized relief requires its own source and ordinary jurisdictional, preservation and remedial conditions.',
    ['Distinct action-creation inquiry and damages-only negative holding: '+source(27,'The asserted federal damages action')+'; unanimous opinion.'],
    extras='**Open question:** Prospective relief, actual exclusion’s legality, forum status, state action, viewer claims and any independently pleaded §1983 route are not decided by this damages holding.')

add(28,'Initiative circulator qualifications and individual identification',SP,
    'Speech burdens imposed on initiative circulators by registered-voter, personal-name and individual-payee requirements.',
    'Excluding otherwise qualified resident-adult initiative circulators solely because they are unregistered voters substantially burdens protected petition conversation; ease of registration does not remove the burden. Traceability justifications must address retained affidavits, signature review, process and targeted fraud enforcement rather than treating voter registration as a necessary speech qualification. A requirement to display the circulator’s personal name during face-to-face advocacy must be justified at that immediate expressive encounter; materially less burdensome post-circulation identification and enforcement matter to fit.\n\nCompelled publication of each paid circulator’s identity, addresses and individual compensation in final or monthly reports requires a substantial relationship to important informational or enforcement interests. The messenger is not automatically a financing source or candidate contributor. Sponsor identity and aggregate spending disclosures retain a distinct financing function. Timing may matter independently, but disclosure during circulation does not cure an insufficient relationship between each messenger’s identity and the asserted interest.',
    ['Voter-registration and badge rules: '+source(28,'I. Registered-voter condition; II. Personal name displayed during solicitation')+'; six direct joins to I, eight to II.',
     'Individual-payee reporting inquiry and timing: '+source(28,'III-A. Final individual-circulator reports; III-B. Monthly individual-circulator reports')+'; six direct joins.'],
    extras='**Exceptions and limits:** These holdings concern Colorado’s reviewed restrictions and their supported burdens and alternatives. Residence, age and circulation-period requirements, standalone paid-status or employer attribution, and independent monthly-report fields are not adjudicated. No categorical initiative-finance disclosure exemption or anonymity from lawful investigation follows; materially narrower reporting requires its own justification.')

add(29,'Warsaw Convention exclusivity within the Article 17 field',LAB,
    'Whether local damages law can avoid unsatisfied Convention conditions for a covered passenger injury occurrence.',
    'When a passenger’s personal-injury occurrence lies within Article 17’s temporal and substantive field, Article 24 subjects the carrier action, whatever its legal foundation, to the Convention’s conditions and limits. Failure to satisfy the accident or bodily-injury condition does not itself remove the occurrence from that field or allow an independent local damages action. Domestic law may identify compensable losses and beneficiaries subject to treaty conditions; it cannot create liability simply because a treaty condition fails.',
    ['Field-based exclusivity and distinction between conditions and coverage: '+source(29,'Part I — Local law cannot avoid the Convention’s conditions within its covered field')+'; eight direct joins.'],
    extras='**Exceptions and limits:** Events outside covered embarking, carriage or disembarking remain outside this rule. Article 25’s full operation when willful misconduct is proved remains open; intentional touching alone does not establish that predicate. No categorical rule about every physical manifestation of emotional injury or every intentional accident is adopted.')

add(30,'Notice after seizure and access to published return procedures',CV,
    'What notice due process requires after criminal seizure of movable property.',
    'The owner must receive timely notice reasonably calculated to identify the seized property and responsible custodian so the owner can seek return. With that notice, due process does not additionally require personalized instructions about adequate state return procedures reasonably ascertainable from generally available statutes and decisions. Publication alone does not establish meaningful access to an inadequate, concealed, misleading, obstructed or practically inaccessible remedy.',
    ['Practical seizure notice and limits on an individualized legal-guide duty: '+source(30,'1. Notice of the seizure does not require an individualized guide to published return procedures')+'; seven direct full-opinion joins.'],
    extras='**Exceptions and limits:** Initial seizure legality, retention, omitted indispensable identifiers and actual obstruction remain independent questions. No comprehensive notice checklist, universal deadline or rule that a warrant satisfies every later process obligation follows.')

modify(32,'Emergency stabilization, conditional transfer and informed refusal',
    'A §1395dd(b) stabilization claim has no additional improper financial or other invidious-motive element. The claimant must still prove the enacted stabilization or transfer duty and applicable civil-action predicates. Subsection (d)(2)(A) permits a directly harmed person to sue the participating hospital for personal-injury damages available under its State’s law and appropriate equitable relief, within two years after the violation; it creates no personal action against an individual physician.',
    ['Absence of additional motive element and retained civil-action conditions: '+source(32,'1. Stabilization has no additional improper-motive element')+'; unanimous per curiam opinion.'],
    'Roberts v. Galen, 1999-01-13, for the motive and specified civil-action components; the carried stabilization, transfer and refusal components retain 1994-12-12.',
    question='A participating hospital’s stabilization, transfer and refusal duties and the additional conditions of a private action after determining an emergency medical condition.')

add(33,'Mathematical applications and commercial use under patent §101','Patents',
    'Whether a business calculation implemented by a programmed machine is an eligible invention.',
    'An otherwise eligible invention is not excluded merely because its use is commercial or concerns financial administration. Conversely, a mathematical calculation does not become eligible solely because it produces a useful financial result, is confined to a named business arrangement or is expressed as a programmed machine. The complete claimed combination must supply a patentable application rather than the calculation with ordinary implementation. All material limitations remain in the whole-claim inquiry; §112, paragraph 6, means-plus-function limitations include corresponding disclosed structure and equivalents. Mathematics and computer use do not themselves establish ineligibility.',
    ['No industry exclusion, no useful-output shortcut and actual whole-claim construction: '+source(33,'Part I-A — Business use supplies no separate exclusion; Part I-B — Useful financial output is insufficient; the actual whole claim controls')+'; unanimous Parts I-A–B.'],
    extras='**Exceptions and limits:** No universal physical-transformation requirement, independent noncomputer-contribution test or rule that every program is abstract is adopted. Novelty, nonobviousness, disclosure and infringement remain separate requirements.')

add(34,'Intervention before a shareholder’s derivative-settlement appeal',FC,
    'Whether an otherwise nonparty shareholder may appeal a derivative settlement solely after appearing and objecting under Rule 23.1.',
    'Notice, shareholder interest and a heard objection under Rule 23.1 do not themselves create appellate party status. An otherwise nonparty shareholder must properly become a party through intervention to appeal the derivative settlement judgment. The opportunity to assist the settlement court by objection differs from authority to continue the corporate litigation on appeal. Review by an actual party and an appropriate appeal from an actual intervention denial remain available under their own conditions.',
    ['Derivative-settlement party status and retained intervention review: '+source(34,'1. Rule 23.1 objection does not itself confer the party status needed for this appeal; 2. Intervention review and nonparty due-process protection remain distinct')+'; five direct joins.'],
    extras='**Exceptions and limits:** No universal prohibition of all nonparty appeals or general duty to intervene to preserve an independent claim follows. Due-process limits on binding genuinely unrepresented persons remain, without creating an appellate entitlement, late-intervention right or collateral remedy by themselves.')

add(35,'APA waiver and substitute-payment equitable liens',FC,
    'Whether §702 waives federal immunity for a lien seeking payment of a private debtor’s obligation from Government property.',
    'Section 702 does not waive immunity for an equitable lien functioning as substitute payment from Government property for a private debtor’s default when no identified retained property belonging to the claimant or specific statutory payment entitlement supports recovery. Equitable form and identification of an account do not establish consent. Specific enforcement of an actual entitlement remains a separate question; the substantive duty, remedy and waiver must each be established.',
    ['Substitute compensation, actual entitlement and remedy-specific consent: '+source(35,'The requested lien supplies substitute compensation without an applicable waiver')+'; unanimous opinion.'],
    extras='**Exceptions and limits:** Not every equitable lien is money damages. The Miller Act’s bond duty does not make the Government a guarantor when it fails to obtain a bond. Independent reviewability and adequate-remedy conditions are not eliminated.')

add(36,'Federal impairment of state insurance regulation','Federal preemption',
    'When a generally applicable federal law impairs state insurance law under the McCarran-Ferguson Act.',
    'Where the state law regulates the business of insurance and the federal law does not specifically relate to that business, federal operation impairs the state scheme if it contradicts state law or frustrates an actual state policy or administration; literal contradiction is not indispensable. An additional private action or greater federal remedy alone does not establish impairment. A shared prohibition is likewise not conclusive compatibility: the court must examine whether the federal action displaces an established exclusive remedial arrangement or another actual state policy.',
    ['Actual-policy impairment and the independent remedial inquiry: '+source(36,'Compatible federal fraud remedies do not impair the actual state insurance scheme')+'; unanimous opinion.'],
    extras='**Exceptions and limits:** Absence of a state statutory private remedy does not alone establish administrative exclusivity. A federal action requiring state-forbidden conduct, nullifying state-approved practice or displacing an enacted exclusive remedy presents its own impairment inquiry; no retrospective state action or hypothetical exclusive scheme is supplied.')

add(38,'Election guidance, authoritative construction and neutral approval thresholds',SP,
    'Due process and compelled-speech objections when an election provision is authoritatively construed after officials supplied contrary guidance.',
    'A neutral judicial construction of an ambiguous election provision does not violate due process merely because officials previously issued a contrary advisory interpretation. The actual official inducement, dissemination, reliance and voting circumstances must be examined for fundamental unfairness; a legally possible construction does not by itself answer a supported inducement claim. A neutral referendum threshold may include blank ballots in the approval denominator without compelling political opposition when blanks remain accurately counted and reported as blanks and the rule does not discriminate among identifiable voters. The legal consequence of abstention is distinct from falsely attributing a message.',
    ['Fundamental-fairness inquiry: '+source(38,'II. The record does not establish fundamental unfairness')+'; unanimous Part II.',
     'Neutral denominator and no compelled attribution: '+source(38,'III. A denominator rule does not compel political speech')+'; eight Associate joins.'],
    extras='**Exceptions and limits:** Deliberate misleading directions, pervasive frustration of an effective choice and false attribution of views remain distinct questions. Federal relief does not authorize replacement of authoritative state law merely because informal advice differed.')

add(39,'FCC implementation of local-competition duties','Environmental and administrative law',
    'Allocation of national rulemaking and state implementation under Communications Act §§201(b), 251 and 252.',
    'Section 201(b) authorizes FCC rules implementing §§251–252, including national standards for the statutory tasks while state commissions retain assigned negotiations, arbitrations, individual rates and other determinations. The implementing authority includes §251(b)(3)’s toll-dialing-parity duty subject to actual statutory limits. Authority to prescribe a methodology does not establish that a particular methodology, rate or implementation duty is lawful. The at-least-equal-quality requirement is a floor; absence of an express superior-quality command does not alone foreclose every implementing requirement for more. Likewise, the direction to enable requesting carriers to combine elements does not unambiguously allocate every physical combining task exclusively to the requester. Particular superior-quality and affirmative new-combination duties require examination of their actual statutory relation, conditions and agency reasons.',
    ['National/state allocation: '+source(39,'I. National implementing rules coexist with state determinations')+'; six direct joins.',
     'Parity authority: '+source(39,'VIII. Dialing-parity authority and numbering-cost ripeness remain distinct')+'; five direct joins in the lead ground.',
     'Construction limits for quality and new combinations: '+source(39,'X. Superior-quality duties return for review under the correct framework; XI. Affirmative new-combination duties require separate reconsideration')+'; eight direct joins to X and seven to XI.'],
    extras='**Open question:** TELRIC’s substantive validity, particular confiscatory rates and the remanded superior-quality and affirmative new-combination rules are not approved by this delegation holding. Compensation alone supplies no authority and nondiscrimination alone does not compel every upgrade.')

add(39,'Telecommunications network elements and bounded access','Environmental and administrative law',
    'Which telecommunications elements may require access and which incumbent combinations and approved-agreement arrangements remain available.',
    'Section 153(29)’s network-element definition includes features, functions and capabilities supplied through facilities or equipment as well as physical facilities. Eligibility does not itself require unbundling. Under §251(d)(2), proprietary necessity and general impairment must independently constrain element selection, including consideration of realistically available alternatives outside as well as inside the incumbent network. Any additional cost or quality decline, with outside alternatives categorically ignored, is insufficient. Technical feasibility may matter but cannot replace those statutory constraints. No irreplaceable-monopoly or numerical threshold is imposed.\n\nSection 251(c)(3) supplies no freestanding requirement that a requesting carrier own local facilities. Particular access remains subject to lawful criteria and conditions. Rule 51.315(b) lawfully prevents dismantling already-combined requested elements unless the requester seeks separation; separately available or valued elements need not be physically destroyed. Under §252(i), Rule 51.809 permits access to an individual arrangement in an approved agreement on the same pertinent rates, terms and conditions, subject to proof of greater provision cost or technical infeasibility and availability only for a reasonable period after public filing. A favorable price cannot be detached from its relevant obligations.',
    ['Definition and eligibility: '+source(39,'III. A network element need not be a detachable physical object; V. The Act imposes no freestanding own-facilities prerequisite')+'; eight direct joins.',
     'Independent necessity/impairment and no technical-feasibility substitute: '+source(39,'IV. Necessity and impairment must perform independent limiting work; IX. Technical feasibility cannot replace the required access criteria')+'; seven direct joins to the complete rules.',
     'Existing combinations and agreement arrangements: '+source(39,'VI. Existing combinations need not be dismantled; VII. An entrant may select an individual agreement arrangement with its pertinent conditions')+'; unanimous Parts VI–VII.'],
    extras='**Exceptions and limits:** No universal whole-network entitlement, approved replacement access list, compelled new configuration or unconstrained selection of agreement terms follows. New-combination duties retain their separate unresolved review.')

add(39,'Ripeness of an announced administrative enforcement forum',FC,
    'Whether a definite agency announcement of possible enforcement authority is immediately fit for judicial resolution.',
    'Completeness of an agency position and predominantly legal character of a dispute do not alone establish ripeness. A general announcement of a possible enforcement forum that directs no present change in primary conduct, determines no particular liability and permits meaningful review of concrete application is not ripe merely because a future complaint may require defense or forum allocation is uncertain. Finality, standing, fitness and hardship remain distinct inquiries.',
    ['Present conduct consequences, review opportunity and independent ripeness inquiry: '+source(39,'XII. The general section 208 announcement is not ripe for review')+'; eight Associates directly join.'],
    extras='**Exceptions and limits:** A presently binding or burdensome statement presents a different question. This rule creates no universal exhaustion requirement or promise of future standing and timeliness, and does not defer every challenge until penalties are collected.')

modify(40,'Constitutional review of census adjustment methodology',
    'The Enumeration Clause permits a genuine population-counting effort combining direct collection with reasoned statistical supplementation; an exclusively physical-headcount method is not constitutionally required. The explanation must address the geographic accuracy and uncertainty relevant to population-based representation; improvement of national totals alone is not enough. The approved follow-up and coverage-measurement design establishes no permissible error rate or automatic superiority and gives no advance approval to unsupported, discriminatory or unauthorized changes.',
    ['Constitutional permission for explained statistical supplementation: '+source(40,'IV. The Constitution permits this explained use of statistical supplementation')+'; Souter, Stone-Zsela, Stevens, Ginsburg and Breyer directly join.'],
    'Department of Commerce / Glavin, 1999-01-25, resolves the constitutional permission question for the stated supplementation design; Wisconsin’s standard remains effective from 1996-03-20.',
    replace={'Rejection of a duty to use the proposed adjustment decides neither whether the Constitution prohibits it nor whether §195’s apportionment exception prohibits sampling or instead removes sampling from that provision’s otherwise mandatory feasible-method direction. Section 141(a) does not alone settle that interaction.':'Department of Commerce / Glavin permits the described nonresponse follow-up and Integrated Coverage Measurement designs under §§141 and 195, but its five supporters adopt no common general construction of §195’s apportionment exception. Neither the plurality’s general-discretion account nor the separate no-replacement proposal is a majority rule. Materially different designs require their own statutory analysis; no fixed-percentage safe harbor or duty to sample for apportionment is established.'})

modify(41,'ERISA sponsor design, fiduciary implementation and genuine benefit payments',
    'Employee contributions do not turn amendment design into fiduciary conduct or make participants co-sponsors. Genuine benefit payments within a continuing single plan do not inure to the employer under §403(c)(1), or become prohibited §406(a)(1)(D) transfers, merely because they reduce employer contributions or payroll costs. Surplus remains plan property. Section 406(b)(2)’s adverse-party prohibition is not triggered merely by sponsor adoption of an advantageous benefit design; independent fiduciary implementation and prohibited transactions retain their actual elements.',
    ['Contributory-plan sponsor capacity, anti-inurement and genuine-payment boundaries: '+source(41,'I. Genuine payments within the continuing plan do not inure to the employer; II. Amendment design is distinct from fiduciary implementation; V. Incidental employer advantage does not make these benefit payments prohibited transactions')+'; nine direct joins to sponsor capacity, eight to the independently stated anti-inurement and transaction grounds.'],
    'Hughes Aircraft, 1999-01-25, for the contributory-plan, anti-inurement and §406(b)(2) components; Spink’s existing components remain effective from 1996-06-10.')

add(41,'Defined-benefit surplus and statutory termination','Labor, employment, and maritime law',
    'Participants’ rights in an overfunded defined-benefit plan and the trigger for termination distribution.',
    'Participants retain promised and statutorily protected accrued benefits, including the employee-contribution floor, but do not presently own individual shares of all actuarial surplus. Mandatory-contribution protection under §§203(a)(1) and 204(c) uses accumulated contributions with the enacted interest treatment and an annual benefit beginning at normal retirement age, with actuarial equivalence for a different form; voluntary contributions retain §204(c)(4)’s distinct treatment. Lawful benefit payments reducing no protected benefit do not themselves establish forfeiture or cutback.\n\nClosing a contributory benefit structure to new entrants while the plan and obligations continue does not itself trigger §4044 termination distribution. A common-law wasting-trust characterization cannot replace §§4041–4042’s statutory termination process. When termination distribution lawfully occurs, plan liabilities and statutory allocation priorities remain, including employee-derived residual protection; employer reversion additionally requires satisfied liabilities, consistency with law and plan authorization, subject to the enacted timing and employee-residual protections.',
    ['Accrued-benefit protection without individual surplus ownership and statutory nontermination: '+source(41,'III. Accrued benefits are protected without individual ownership of all surplus; IV. Continuing benefit obligations do not trigger termination distribution')+'; nine direct joins to the common holdings, eight to the statutory contribution and distribution explanations.'],
    extras='**Exceptions and limits:** No actual benefit amount, reversion entitlement or general rule for every partial termination follows. A fair-administration clause alone does not promise a later incentive to persons outside its lawful eligibility class or authorize judicial redesign; a due benefit, unequal administration among eligible participants or independent statutory restriction retains its own claim. Authority: the same Record, Holding VI, eight direct joins.')

add(43,'Primary attribution of an auditor’s private approval','Civil RICO and securities liquidation',
    'When private auditor review becomes an investor-facing representation by that auditor.',
    'Private review and oral approval alone do not make an issuer’s expressly unaudited release the auditor’s own public certification where no auditor representation was communicated or attributed to investors. A general market expectation of auditor involvement supplies no missing representation. Primary responsibility for one’s own deception remains distinct from the separately available action for culpable affirmative substantial assistance; undisclosed assistance or absence of public attribution does not categorically defeat that assistance theory.',
    ['Primary-speaker boundary and preservation of the distinct assistance route: '+source(43,'I. Private approval does not itself make the auditor the public speaker; II. The preserved assistance allegations require application of Central Bank')+'; unanimous opinion.'],
    extras='**Exceptions and limits:** No universal public-name requirement is adopted for every deceptive act, agency, scheme or indirect communication. Actual auditor reports, independently attributed statements and direct market deception require their own analysis; ordinary professional error remains insufficient under the carried assistance rule.')

add(45,'Assigned school productions and teachers’ personal speech',LAB,
    'Whether a teacher has a personal First Amendment right over an assigned school instructional production.',
    'Selection, production and direction of material as part of an assigned public-school instructional program are institutional curricular expression subject to the school system’s lawful control. Delegated artistic discretion, public controversy and prior approval do not themselves give the teacher a personal constitutional right against curricular and related employment control or make approval an irrevocable constitutional delegation. A protected personal interest must be established before justification and same-decision rules apply.',
    ['Confined instructional-expression classification and antecedent personal-interest requirement: '+source(45,'Assigned instructional production and the asserted personal speech right')+'; five direct joins.'],
    extras='**Exceptions and limits:** Separate citizen speech, independently forbidden classifications or exclusions, and statutory, contractual, tenure and state-law limits remain. This is not a rule for every duty-related statement or university academic freedom, and a curricular label does not establish an actually lawful motive.')

add(46,'Common-issue aggregation and meaningful individual defenses',FC,
    'Due-process conditions for state consolidation of genuinely common issues.',
    'A State may try genuinely common issues together only if each defendant can meaningfully contest the evidence and every material defense to those issues, with remaining claimant-specific elements still required. Party numbers and omission of brand names from a verdict form do not alone establish a violation, but efficiency cannot replace legally necessary individual proof. Representative trial plaintiffs do not statistically establish other claimants’ exposure, causation, injury or damages, and a product category cannot decide a materially different characteristic without fair adjudication. Later proceedings may apply only the common findings lawfully resolved; a later individual trial cannot cure a material defense already foreclosed.',
    ['Actual common issue, meaningful defense, individual proof and scope of later findings: '+source(46,'I. Common issues may be tried together only with a meaningful defense; III. The affirmance preserves individual proof and distinct remedies')+'; unanimous opinion.'],
    extras='**Exceptions and limits:** No numerical ceiling, brand-name-verdict rule, authority to bind strangers or categorical appellate cure follows. The actual procedural device’s requirements govern; federal settlement-class rules are not automatically imported into state consolidation.')

add(47,'Title IX recipient status and ordinary membership dues',CV,
    'Whether an association receives federal financial assistance merely through dues paid by federally assisted institutions.',
    'Ordinary membership dues from assisted institutions do not alone make the association a Title IX recipient. Assistance may reach a recipient through an intermediary, but an ordinary downstream payment is not automatically assistance extended to the payee. Section 1687 expands covered operations after assistance reaches part of the defined entity; it does not remove that receipt condition, including for an entity established by multiple listed institutions. Section 106.2(h)’s receiving-or-benefiting language likewise does not erase the requirement that assistance be extended directly or through another recipient.',
    ['Receipt distinguished from economic benefit and retained statutory/regulatory condition: '+source(47,'I. Ordinary membership dues do not alone establish receipt of federal assistance')+'; unanimous opinion.'],
    extras='**Open question:** Actual assistance through a separate program or fund and independently sufficient delegated-control coverage require their own properly preserved factual and legal basis. No amount or percentage of dues supplies a new threshold or exemption.')

add(48,'Review of Medicare reimbursement reopening refusals','Environmental and administrative law',
    'Which statutory routes permit review of an intermediary’s refusal to reopen a final Medicare reimbursement determination.',
    'A discretionary refusal to reopen is not a new final determination of total program reimbursement under §1395oo(a)(1)(A)(i). Judicial review of the Board’s final jurisdictional ruling under §1395oo(f)(1) permits deciding that boundary; it does not authorize Board review of the refusal or direct judicial calculation. Section 405.1885(c) leaves reopening with the body that last decided the matter, while §405.1889 separately recognizes review of an actual revision in reimbursement after reopening. A request for reopening to obtain additional Medicare payment arises under that scheme; describing it as procedural does not avoid incorporated §405(h)’s bar on the asserted §1331 route. The APA supplies no independent subject-matter jurisdiction.',
    ['Refusal distinguished from a new determination and separate regulatory allocation: '+source(48,'I. Refusal to reopen is not a new appealable reimbursement determination')+'; nine direct joins to the statutory ground, eight to the regulatory ground.',
     'Medicare arising-under channel and absence of APA jurisdiction: '+source(48,'II. The claim cannot proceed directly under federal-question jurisdiction; III. The APA supplies no independent jurisdiction')+'; eight direct joins.'],
    extras='**Exceptions and limits:** Timely original appeals, actual revised determinations, properly presented regulatory procedural violations and independently authorized constitutional claims retain their conditions. No colorable constitutional claim was decided. This is not a categorical declaration that every reopening-related action is unreviewable.')

add(48,'Medicare reopening duties and mandamus','Environmental and administrative law',
    'When the reimbursement reopening regulations impose a clear nondiscretionary reopening duty.',
    'Section 405.1885(a) permits reopening on a timely motion and ordinarily requires a request within three years after notice; later reopening is barred except under paragraphs (d) and (e). New evidence or alleged error alone does not command reopening. Paragraph (b) requires reopening and revision when HCFA, within those three years, notifies the intermediary that the determination or hearing decision conflicts with applicable law, regulations or general HCFA instructions issued under the Secretary’s agreement. Paragraph (d) requires reopening and revision at any time when a party procured the determination or decision by fraud or similar fault. A provider’s allegation is neither HCFA notice nor proof of fraud. Paragraph (e)’s historical transition applies (a) and (b) to periods ending on or after December 31, 1971, and the three-year limit to earlier periods reopened after May 27, 1972.\n\nUnder §405.1887, reopening requires written notice, an explanation if revision follows, and a reasonable opportunity for additional evidence or argument. Those requirements do not command that every request be granted. General reasonable-cost or corrective-adjustment obligations do not alone establish the clear reopening duty necessary for mandamus; manual considerations cannot override the regulations’ separate commands.',
    ['Reopening predicates, procedural duties and absence of mandamus from general reimbursement law: '+source(48,'IV. No clear duty to reopen these determinations supports mandamus')+'; eight direct joins.'],
    extras='**Open question:** Whether incorporated §405(h) universally precludes §1361 mandamus is unresolved. A claimant must still satisfy mandamus’s actual prerequisites, including exhaustion of available avenues; accuracy of a reimbursement claim alone supplies no clear reopening duty.')

modify(49,'Immigration transition, completed adjudication and AEDPA review limits',
    'Section 1252(g)’s named-action withdrawal includes a selection challenge to commencement or adjudication; a constitutional label or potential later final-order petition does not move it outside those acts, and continuing proceedings is not a fourth enumerated act. Nevertheless, §1252(g) does not foreclose existing §1331 jurisdiction over a substantial constitutional selection claim where the claimant has a concrete personal controversy, the actual immigration process cannot adjudicate that claim, and the applicable judicial-review provisions cannot receive its necessary factual record. Constitutional or collateral labeling, disagreement with discretion and preference for earlier review are insufficient. The original basis is §1331 and the existing constitutional action against federal officers, not a jurisdictional grant in §1252(f)(1)’s individual-relief exception. Retained access does not itself establish interim or final relief. Section 1252(f)(2)’s clear-and-convincing condition concerns injunction of removal under a final order, not proceedings without such an order.',
    ['Named-action coverage and distinct remedy restrictions: '+source(49,'I-A. The withdrawal reaches the named acts in these pending proceedings; I-B. The individual-relief exception does not grant jurisdiction')+'; eight direct joins.',
     'Confined constitutional-access construction: '+source(49,'III-B. A confined construction preserves a capable constitutional forum')+'; Souter, Stevens, O’Connor, Ginsburg and Breyer directly join.'],
    'Reno v. American-Arab Anti-Discrimination Committee, 1999-02-24, for the confined §1252(g) constitutional-access boundary and §1252(f) distinctions; the carried temporal and §2241 components retain their earlier dates.',
    replace={'the consequences of a demonstrated failure of the retained route, and general reopening of factual or discretionary questions.':'the constitutional consequences of a demonstrated failure of a retained route, and general reopening of factual or discretionary questions. AADC supplies the stated narrow construction where the actual selection claim otherwise lacks a capable forum; whether the Constitution itself demands the same access absent that construction, or where an adequate later route exists, remains open.'})

add(49,'Necessary factual records in former immigration final-order review','Immigration',
    'Whether former §1105a(a) and 28 U.S.C. §2347 supply a district-court evidence route for a selection claim outside the administrative record.',
    'Former §1105a(a)(4)’s administrative-record restriction, subject to the separate nationality transfer in (5)(B), and §2347’s hearing conditions must both be satisfied. Section 2347(a) uses the agency record when a hearing occurred. Subsection (b) first requires that no hearing preceded the action reviewed; it then requires agency remand if a hearing was legally required, permits decision on pleadings and affidavits if none was required and no genuine material factual dispute exists, and permits district-court transfer if none was required and a genuine material factual dispute exists. A final deportation order following a required hearing cannot be converted into a no-required-hearing action by relabeling the earlier charging decision while retaining the final order as the jurisdictional trigger. Subsection (c)’s additional-agency-evidence route separately requires materiality and reasonable grounds for earlier omission, subject to any applicable statutory withdrawal.',
    ['Combined record restriction and precise hearing/transfer sequence: '+source(49,'II. The proposed factual transfer does not make this final-order channel adequate')+'; eight direct joins.'],
    extras='**Exceptions and limits:** Agency inability to decide selection does not erase the record restriction, and an already developed district-court record cannot be imported without authority. Party advocacy, stipulation or a proposed procedural mechanism cannot create jurisdiction. The rule does not decide every constitutional legal question on a proper administrative record or establish new discovery or trial rights.')

add(51,'State tax on independent federal reservation contractors','Indian law',
    'A nondiscriminatory gross-receipts tax on an independent nonmember contractor performing ordinary federal work on a reservation.',
    'Where legal incidence falls on an independent nonmember contractor, a State may impose the nondiscriminatory gross-receipts tax on ordinary federal reservation construction absent applicable constitutional immunity or a controlling federal exemption. Federal payment, supervision, reservation location and tribal benefit do not alone exempt the contractor or require Bracker/Ramah balancing for the federal transaction. Economic reimbursement does not make the contractor the United States, and indirect economic burden does not replace the legal-incidence inquiry.',
    ['Federal-contract transaction, legal incidence and no automatic tribal-balancing route: '+source(51,'Federal contracts on a reservation do not themselves exempt the contractor')+'; unanimous opinion.'],
    extras='**Exceptions and limits:** Direct federal or tribal taxes, genuine federal instrumentalities, discrimination, actual federal exemptions and contracts with tribes retain distinct treatment. The Buy Indian preference and the cited self-determination choice and BIA-sanctions regulations supply no general downstream state-tax exemption.')

add(52,'Conditional serious-harm intent under the carjacking statute',CR,
    'The purpose required by the amended §2119 intent-to-kill-or-cause-serious-bodily-harm element.',
    'At the moment of demanding or taking control of the vehicle, an actual settled intent to kill or cause serious bodily harm if necessary to complete the taking satisfies §2119. The Government must prove that defendant’s own purpose beyond a reasonable doubt. Intimidation alone, an empty threat, recklessness, an accomplice’s purpose alone or purpose first formed afterward is insufficient. The statute does not additionally require that resistance be objectively probable or expected; that evidence may bear on whether the conditional purpose was real without becoming a separate element.',
    ['Actual conditional purpose, timing and proof limits: '+source(52,'A settled intent to inflict serious harm if necessary for the taking satisfies section 2119')+'; seven direct joins.'],
    extras='**Exceptions and limits:** Gun possession supplies no automatic intent inference. This construction adopts no general Model Penal Code formula and decides no unpreserved separate instruction request.')

modify(53,'Habeas and §2255 appeals and appellate certificates',
    'An authorized judge’s actually issued, issue-specific certificate admits the identified claim to appeal even when the judge allegedly erred in assessing §2253(c)(2)’s constitutional showing. That alleged assessment error does not itself nullify the existing appellate authorization. The substantial-constitutional-showing condition remains necessary for proper issuance; this rule neither finds a bare rules claim sufficient nor authorizes future certificates without the statutory showing.',
    ['Issued authorization distinguished from correctness of the constitutional-showing assessment: '+source(53,'The issued certificate supplied the appellate authorization in this case')+'; eight Associate joins.'],
    'Peguero, 1999-03-02, for the effect of an actually issued certificate; Hohn and enacted certificate procedures retain their stated dates.')

add(53,'Appeal-warning omissions and causal loss on §2255 review',CR,
    'Collateral relief for failure to give the appeal advice required by Rule 32.',
    'The sentencing judge must give the required appeal advice despite independent knowledge. But actual knowledge and an unchallenged voluntary decision not to appeal can establish that the omission caused no lost appeal; the rule violation alone then does not require §2255 relief. Causal deprivation is distinct from probable appellate success: a person actually deprived of an appeal need not prove the lost appeal would have succeeded.',
    ['Mandatory advice, causal loss and no meritorious-appeal substitute: '+source(53,'A mandatory warning error does not restore an appeal that the omission did not cause the defendant to lose')+'; unanimous Part II.'],
    extras='**Exceptions and limits:** No universal clear-and-convincing burden on disputed knowledge, presumption that cooperation waives appeal or procedure for future contested cases is adopted. The scope of a restored appeal is not resolved.')

add(54,'Private payment choices and governmental attribution',CV,
    'Whether statutory permission and public review mechanisms make a private compensation carrier’s initial withholding state action.',
    'Private carriers’ independent decisions to dispute treatment and withhold payment pending utilization review are not state action merely because the State permits that course, requires compensation coverage and supplies review machinery. Attribution requires an actual governmental basis of responsibility for the challenged choice, such as compulsion, significant encouragement, joint participation or an exclusively governmental function. Screening for proper invocation and assigning a reviewer do not by themselves substantively approve the medical objection or order the initial suspension.',
    ['Choice-specific attribution and limited significance of permission and review: '+source(54,'Statutory permission does not itself make the private carrier’s payment choice governmental')+'; seven direct joins.'],
    extras='**Exceptions and limits:** The legislature’s own act, a public obligor, an official review decision or a distinct proved attribution basis requires its own inquiry. The ruling does not make all acts in the compensation system private.')

add(54,'Conditional workers’ compensation medical-payment interests',CV,
    'Whether general compensation eligibility creates an unconditional right to advance payment for every disputed medical service.',
    'General eligibility does not by itself establish a constitutional right to constant advance payment of every disputed service before its reasonable-and-necessary character is established. A protected claim to fair adjudication remains distinct from an unconditional payment entitlement. The rule does not defeat an existing service-specific entitlement, operative prior award or legally sufficient expectation of continued payment merely because an insurer invokes review; an objection cannot define substantive property away through procedure.',
    ['Conditional payment right and preservation of adjudication and specific entitlements: '+source(54,'General eligibility does not establish an unconditional right to advance payment of every disputed service')+'; eight direct joins.'],
    extras='**Exceptions and limits:** Prior orders and payments require actual consideration; reimbursement and interest are not presumed to replace medical care lost during interruption. No universal procedure-adequacy finding, new exhaustion duty or proof requirement follows.')

add(55,'Necessary nonphysician school-health services under IDEA','Education and equal protection',
    'Whether continuous or costly school-health assistance falls within IDEA’s related-services duty.',
    'IDEA requires qualified nonphysician school-health services necessary during the school day for an eligible child to attend and benefit from special education even when availability must be continuous and services are costly. The medical-services exclusion concerns services requiring a physician, except diagnosis and evaluation. Educational necessity and lawful qualifications remain; care appropriately furnished outside school hours need not be supplied at school. No additional local affordability, complexity, continuity or existing-staff exclusion applies. The express related-services duty, school-health regulation and Tatro construction supply clear funding notice of this covered service category despite substantial need.',
    ['Service category, continuity and cost boundary: '+source(55,'Necessary nonphysician school-health services are covered despite continuity and cost')+'; seven direct joins.',
     'Specified funding notice: '+source(55,'The existing statutory service obligation supplies clear funding notice')+'; six direct joins.'],
    extras='**Exceptions and limits:** The rule requires neither experimental treatment, unrelated services nor physician care outside diagnosis or evaluation. It does not choose a provider, override licensing, imply a new §1983 action or create a general program-adequacy injunction.')

add(57,'Bounded FLRA choice over midterm bargaining',LAB,
    'The federal labor statute’s allocation of authority over union-initiated bargaining during an existing agreement.',
    'The statute neither categorically prohibits union-initiated midterm bargaining nor unambiguously requires one comprehensive midterm regime. The FLRA may determine timing and extent through a reasonable, explained construction subject to contract coverage, lawful waiver, negotiable-subject restrictions, management rights and federal-law consistency. Section 7106(b)(1)’s agency-election condition is not automatically a condition in (b)(2) or (3). Efficiency and impasse provisions inform administration without establishing perpetual negotiation or inevitable clause imposition. Absence of an independently compelled statutory entitlement does not itself make a contractual midterm proposal unlawful; the actual clause and the agency’s reasons must be examined under the permissible framework.',
    ['Genuine bounded discretion and separate contractual negotiability: '+source(57,'1. The statute leaves the extent of midterm bargaining to bounded Authority construction; 2. Contractual negotiability requires reconsideration under the corrected legal framework')+'; six direct joins.'],
    extras='**Exceptions and limits:** No compulsory agreement, concession or Panel award is supplied. Agreed waiver, bargaining over a waiver clause and compulsory acceptance at impasse are distinct; no comprehensive employer-imposed waiver is presumed. Statutory silence alone does not satisfy §§7103(a)(14)(C) and 7117(a).')

add(58,'Renewed execution-method election and the particular method objection',CR,
    'Effect of affirmatively selecting and reaffirming the challenged execution method when the available statutory alternative remains unchallenged.',
    'A prisoner who affirmatively selects lethal gas while injection is the available statutory alternative and default, and reaffirms that selection after an express opportunity to choose injection, waives this particular gas-method objection when injection is not challenged in the present proceeding. The repeated affirmative election is distinct from silence or failure to discover an unfamiliar procedure.',
    ['Confined renewed-election waiver: '+source(58,'I. The particular renewed method election defeats this gas objection')+'; seven direct joins.'],
    extras='**Exceptions and limits:** The rule decides neither the empirical constitutionality of either method nor whether every capital protection may be waived. It creates no universal alternative-method requirement or global finding about advice or capacity. Reasonable availability for default cause remains distinct from final adequate-and-independent-bar analysis, Teague classification and other preserved claims.')

